#!/usr/bin/env bash
# Pill pitch cut v11: 12 cuts + 4-s end card = 147.83 s, 1080x1920 (source is portrait: 1024x576 with -90° rotation).
# Generated by make_edit.py (edit the cut list there, re-run it, never hand-edit the graph).
#   bash pitch/video/edit/build.sh            full render  -> pitch/vid../pill-pitch-v12-nomusic.mp4
#   bash pitch/video/edit/build.sh --preview  seconds 0-10 -> pitch/video/pill-pitch-preview10.mp4
#   bash pitch/video/edit/build.sh --check    filtergraph dry run: 0.1 s to the null muxer, no encode
set -euo pipefail
cd "$(dirname "$0")"
SRC=../../video-raw/preston-pitch-raw.mp4
MUSIC=${MUSIC:-work/music-long.wav}   # original score synthesised by make_music.py (116 BPM), no licence needed
FF=${FFMPEG:-bin/ffmpeg}          # needs libass (the 'ass' filter); Homebrew's ffmpeg 8.1.2 has none
if ! "$FF" -hide_banner -filters 2>/dev/null | grep ' ass ' >/dev/null; then
  echo "fetching a static ffmpeg with libass into bin/ (martin-riedl.de, macOS arm64)"
  mkdir -p bin && curl -sSfL -o bin/ffmpeg.zip https://ffmpeg.martin-riedl.de/redirect/latest/macos/arm64/release/ffmpeg.zip
  (cd bin && unzip -o -q ffmpeg.zip && rm ffmpeg.zip && chmod +x ffmpeg && xattr -c ffmpeg 2>/dev/null || true)
  FF=bin/ffmpeg
fi
[ -f "$MUSIC" ] && [ -f sfx/whoosh.wav ] || { echo "missing $MUSIC or sfx/whoosh.wav: run .venv/bin/python make_music.py 152 && mv work/music-fun.wav $MUSIC"; exit 1; }
[ -f fonts/Inter-Medium.ttf ] && [ -f fonts/Inter-SemiBold.ttf ] && [ -f fonts/Inter-Bold.ttf ] || { echo "missing static Inter: run .venv/bin/python make_fonts.py"; exit 1; }
MODE=${1:-full}
case "$MODE" in
  --preview) OUTARGS=(-t 10 -c:v libx264 -preset veryfast -crf 23 -pix_fmt yuv420p -c:a aac -b:a 160k -movflags +faststart ../pill-pitch-preview10.mp4) ;;
  --check)   OUTARGS=(-t 0.1 -f null -) ;;
  full)      OUTARGS=(-c:v libx264 -preset medium -crf 20 -profile:v high -pix_fmt yuv420p -r 30 -c:a aac -b:a 192k -ar 48000 -movflags +faststart ../pill-pitch-v12-nomusic.mp4) ;;
  *) echo "usage: build.sh [--preview|--check]"; exit 2 ;;
esac
"$FF" -hide_banner -y -nostdin \
  -ss 44.300 -t 4.280 -i "$SRC" \
  -ss 8.200 -t 5.400 -i "$SRC" \
  -ss 13.800 -t 9.450 -i "$SRC" \
  -ss 27.650 -t 7.950 -i "$SRC" \
  -ss 49.850 -t 18.500 -i "$SRC" \
  -ss 68.350 -t 16.050 -i "$SRC" \
  -ss 84.400 -t 19.500 -i "$SRC" \
  -ss 103.900 -t 8.550 -i "$SRC" \
  -ss 112.450 -t 12.250 -i "$SRC" \
  -ss 124.700 -t 9.150 -i "$SRC" \
  -ss 147.400 -t 16.000 -i "$SRC" \
  -ss 163.900 -t 15.300 -i "$SRC" \
  -f lavfi -t 4.0 -i "color=c=0xF4EFE6:s=1080x1920:r=30" \
  -f lavfi -t 4.0 -i "anullsrc=r=48000:cl=stereo" \
  -i "$MUSIC" \
  -ss 125.100 -t 2.535 -i "$SRC" \
  -f lavfi -t 3.5 -i "color=c=black:s=1080x1920:r=30" \
  -f lavfi -t 3.5 -i "anullsrc=r=48000:cl=stereo" \
  -i fx/anim/intro-card.mov \
  -loop 1 -framerate 30 -t 1.80 -i stickers/pop-think.png \
  -i fx/words/pill-pop.mov \
  -i fx/words/pill-pop.mov \
  -loop 1 -framerate 30 -t 3.20 -i stickers/pill.png \
  -loop 1 -framerate 30 -t 1.60 -i fx/stickers/sparkle.png \
  -loop 1 -framerate 30 -t 3.00 -i stickers/pop-step1.png \
  -loop 1 -framerate 30 -t 4.36 -i stickers/pop-step2.png \
  -i fx/words/pill-pop.mov \
  -loop 1 -framerate 30 -t 3.20 -i stickers/chip-402.png \
  -loop 1 -framerate 30 -t 2.20 -i fx/stickers/arrow-curl.png \
  -i fx/words/water-magic.mov \
  -loop 1 -framerate 30 -t 3.80 -i stickers/pop-3d.png \
  -loop 1 -framerate 30 -t 1.60 -i fx/stickers/sparkle.png \
  -loop 1 -framerate 30 -t 5.05 -i stickers/pop-step3.png \
  -i fx/words/water-magic.mov \
  -loop 1 -framerate 30 -t 2.00 -i stickers/pop-drop.png \
  -loop 1 -framerate 30 -t 2.50 -i fx/stickers/circle-scribble.png \
  -loop 1 -framerate 30 -t 2.60 -i stickers/arrow.png \
  -loop 1 -framerate 30 -t 4.19 -i stickers/pop-step4.png \
  -loop 1 -framerate 30 -t 2.00 -i stickers/pop-eyes.png \
  -i fx/anim/sparkle-burst.mov \
  -i fx/words/pill-pop.mov \
  -i fx/words/shake-flash.mov \
  -i fx/words/shake-flash.mov \
  -loop 1 -framerate 30 -t 2.60 -i fx/stickers/badge-one-tablet.png \
  -i fx/words/pill-pop.mov \
  -loop 1 -framerate 30 -t 1.50 -i fx/stickers/sparkle.png \
  -loop 1 -framerate 30 -t 4.44 -i stickers/pop-step5.png \
  -loop 1 -framerate 30 -t 3.20 -i stickers/ring.png \
  -i fx/anim/countdown-ring.mov \
  -loop 1 -framerate 30 -t 5.20 -i stickers/chip-unoq.png \
  -loop 1 -framerate 30 -t 2.40 -i fx/stickers/arrow-curl.png \
  -i fx/anim/arrow-point.mov \
  -loop 1 -framerate 30 -t 6.75 -i stickers/pop-lights.png \
  -loop 1 -framerate 30 -t 2.50 -i fx/stickers/circle-scribble.png \
  -loop 1 -framerate 30 -t 3.40 -i stickers/chip-box.png \
  -loop 1 -framerate 30 -t 4.90 -i stickers/pop-measure.png \
  -loop 1 -framerate 30 -t 2.40 -i fx/stickers/underline-swoosh.png \
  -loop 1 -framerate 30 -t 2.00 -i fx/stickers/arrow-curl.png \
  -i fx/words/water-magic.mov \
  -i fx/words/water-magic.mov \
  -loop 1 -framerate 30 -t 3.50 -i stickers/chip-explains.png \
  -loop 1 -framerate 30 -t 2.60 -i stickers/pop-eyes.png \
  -i fx/anim/answers-bounce.mov \
  -loop 1 -framerate 30 -t 2.60 -i stickers/pop-grimace.png \
  -loop 1 -framerate 30 -t 2.40 -i fx/stickers/bubble-wow.png \
  -loop 1 -framerate 30 -t 2.40 -i stickers/pill.png \
  -i fx/words/pill-pop.mov \
  -i fx/anim/confetti.mov \
  -loop 1 -framerate 30 -t 3.70 -i stickers/pill.png \
  -i fx/anim/pill-rain.mov \
  -loop 1 -framerate 30 -t 3.10 -i stickers/pop-end.png \
  -i sfx/pop.wav \
  -i sfx/whoosh.wav \
  -i sfx/uhoh.wav \
  -i sfx/ding.wav \
  -i sfx/thud.wav \
  -i sfx/plop.wav \
  -i sfx/water.wav \
  -/filter_complex graph.txt \
  -map "[vout]" -map "[aout]" "${OUTARGS[@]}"
[ "$MODE" = --check ] || ls -la ../pill-pitch-*.mp4
